class JWTAuthenticationMiddleware(AuthenticationMiddleware):
    def process_request(self, request):
        try:
            authorization_header = request.META.get('HTTP_AUTHORIZATION')
            if authorization_header:
                token = authorization_header.split()[1]
                try:
                    payload = jwt.decode(token, settings.SECRET_KEY, algorithms=['HS256'])
                    user_id = payload.get('user_id')
                    request.user = User.objects.get(id=user_id)
                except jwt.ExpiredSignatureError:
                    return HttpResponse("Token has expired", status=401)
                except jwt.InvalidTokenError:
                    return HttpResponse("Invalid token", status=401)

            else:
                return super().process_request(request)

        except User.DoesNotExist:
            return HttpResponse("User not found", status=401)
        except jwt.DecodeError:
            return HttpResponse("Invalid token", status=401)

    def process_response(self, request, response):
        return response

def max_balance(n, blue_cards, m, red_cards):
    blue_card_counts = {}
    red_card_counts = {}

    # Count occurrences of strings on blue and red cards
    for card in blue_cards:
        if card in blue_card_counts:
            blue_card_counts[card] += 1
        else:
            blue_card_counts[card] = 1

    for card in red_cards:
        if card in red_card_counts:
            red_card_counts[card] += 1
        else:
            red_card_counts[card] = 1

    max_earnings = 0

    # Iterate over all unique strings
    for card in set(blue_cards + red_cards):
        earnings = blue_card_counts.get(card, 0) - red_card_counts.get(card, 0)
        # Update max earnings
        max_earnings = max(max_earnings, earnings)

    return max_earnings


