def __init__(self):
    self.memo = {}
def knapSack(self,W, wt, val, n):

    if n == 0 or W == 0 :
        return 0
    if n in self.memo:
        return self.memo[n]
    else:
        if wt[n-1] > W:
            self.memo[n] = self.knapSack(W, wt, val, n-1)
            return self.memo[n]

        self.memo[n] = max( self.knapSack(W, wt, val, n-1), (val[n-1] + self.knapSack(W-wt[n-1], wt, val, n-1)) )
        return self.memo[n]

class Scan_Query:
    def __init__(self, n, q):
        self.q = q
        self.n = n
        self.data = [1 << 31 - 1] * MAXN
        self.query = [None] * q
        self.result = [None] * q

    def update(self, i, x):
        self.data[i + MAXN] = x

        j = i + MAXN
        while True:
            j //= 2
            self.data[j] = min(self.data[2 * j], self.data[2 * j + 1])
            if j == 1:
                break

    def find(self, s, t):
        left = s + MAXN
        right = t + MAXN - 1

        ans = 1 << 31 - 1
        while left <= right:
            if left & 1:
                ans = min(ans, self.data[left])
                left += 1

            if right & 1:
                ans = min(ans, self.data[right])
                right -= 1

            left //= 2
            right //= 2

        return ans


