/**
 *
 * @author CovertJaguar 
 */
public enum EnumWallAlpha implements WallInfo {

    INFERNAL_BRICK,
    SANDY_BRICK,
    CONCRETE,
    SNOW,
    ICE,
    STONE_BRICK,
    STONE_BRICK_MOSSY,
    STONE_BRICK_CRACKED,
    STONE_BRICK_CHISELED,
    NETHER_BRICK,
    BRICK,
    SANDSTONE,
    SANDSTONE_CHISELED,
    SANDSTONE_SMOOTH,
    OBSIDIAN,
    FROST_BOUND_BRICK;
    public static final EnumWallAlpha[] VALUES = values();
    private Block source;
    private int sourceMeta = 0;

    public static void initialize() {
        INFERNAL_BRICK.source = BlockBrick.infernal;
        SANDY_BRICK.source = BlockBrick.sandy;
        FROST_BOUND_BRICK.source = BlockBrick.frostbound;
        CONCRETE.source = BlockCube.getBlock();
        CONCRETE.sourceMeta = EnumCube.CONCRETE_BLOCK.ordinal();

        SNOW.source = Blocks.snow;
        ICE.source = Blocks.ice;

        STONE_BRICK.source = Blocks.stonebrick;
        STONE_BRICK.sourceMeta = 0;
        STONE_BRICK_MOSSY.source = Blocks.stonebrick;
        STONE_BRICK_MOSSY.sourceMeta = 1;
        STONE_BRICK_CRACKED.source = Blocks.stonebrick;
        STONE_BRICK_CRACKED.sourceMeta = 2;
        STONE_BRICK_CHISELED.source = Blocks.stonebrick;
        STONE_BRICK_CHISELED.sourceMeta = 3;

        NETHER_BRICK.source = Blocks.nether_brick;

        BRICK.source = Blocks.brick_block;

        SANDSTONE.source = Blocks.sandstone;
        SANDSTONE.sourceMeta = 0;
        SANDSTONE_CHISELED.source = Blocks.sandstone;
        SANDSTONE_CHISELED.sourceMeta = 1;
        SANDSTONE_SMOOTH.source = Blocks.sandstone;
        SANDSTONE_SMOOTH.sourceMeta = 2;

        OBSIDIAN.source = Blocks.obsidian;

//        QUARTZ.source = Block.blockNetherQuartz;

        for (EnumWallAlpha wall : VALUES) {
            if (wall.isEnabled() && wall.source != null) {
                if (wall == NETHER_BRICK) {
                    CraftingPlugin.addShapedRecipe(wall.getItem(5), "S S", "SSS", 'S', wall.getSourceItem());
                } else {
                    CraftingPlugin.addShapedRecipe(wall.getItem(6), "SSS", "SSS", 'S', wall.getSourceItem());
                }
            }
        }
    }

    public static WallInfo fromMeta(int id) {
        if (id < 0 || id >= VALUES.length) {
            return VALUES[0];
        }
        return VALUES[id];
    }

    @Override
    public Block getSource() {
        return source;
    }

    @Override
    public int getSourceMeta() {
        return sourceMeta;
    }

    @Override
    public ItemStack getSourceItem() {
        if (source == null) return null;
        return new ItemStack(source, 1, sourceMeta);
    }

    @Override
    public Block getBlock() {
        return BlockRailcraftWall.getBlockAlpha();
    }

    @Override
    public ItemStack getItem() {
        return getItem(1);
    }

    @Override
    public ItemStack getItem(int qty) {
        Block block = getBlock();
        if (block == null) return null;
        return new ItemStack(block, qty, ordinal());
    }

    @Override
    public String getTag() {
        return "tile.railcraft.wall." + name().replace("_", ".").toLowerCase(Locale.ENGLISH);
    }

    @Override
    public boolean isEnabled() {
        return ModuleManager.isModuleLoaded(Module.STRUCTURES) && RailcraftConfig.isSubBlockEnabled(getTag()) && getBlock() != null;
    }

    @Override
    public float getBlockHardness(World world, int x, int y, int z) {
        switch (this) {
            case CONCRETE:
                return EnumCube.CONCRETE_BLOCK.getHardness();
            default:
                Block block = getSource();
                if (block == null) {
                    return Blocks.brick_block.getBlockHardness(world, x, y, z);
                }
                return block.getBlockHardness(world, x, y, z);
        }
    }

    @Override
    public float getExplosionResistance(Entity entity) {
        switch (this) {
            case CONCRETE:
                return EnumCube.CONCRETE_BLOCK.getResistance() * 3f / 5f;
            default:
                Block block = getSource();
                if (block == null) {
                    return Blocks.brick_block.getExplosionResistance(entity);
                }
                return block.getExplosionResistance(entity);
        }
    }
}

package science.atlarge.opencraft.opencraft.entity.ai;

import com.google.common.collect.ClassToInstanceMap;
import com.google.common.collect.MutableClassToInstanceMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentSkipListSet;
import science.atlarge.opencraft.opencraft.entity.GlowLivingEntity;

public class TaskManager {

    private final GlowLivingEntity entity;
    private final Map<String, EntityTask> tasksByName = new ConcurrentHashMap<>();
    private final ClassToInstanceMap tasksByClass = MutableClassToInstanceMap.create(
            new ConcurrentHashMap<>());
    private final Set tasks = new ConcurrentSkipListSet<>();

    public TaskManager(GlowLivingEntity entity) {
        this.entity = entity;
    }

    /**
     * Returns the existing task with a given name.
     *
     * @param name the name to look up
     * @return the task with that name, or null if no registered task matches
     */
    public EntityTask getTask(String name) {
        return tasksByName.get(name);
    }

    /**
     * Returns the existing task whose class is exactly a given class (and not a subclass -- this
     * will always return null for an abstract type).
     *
     * @param clazz the class to look up
     * @return one of this manager's tasks that's an instance of that class and not a subclass, or
     *         null if no such tasks are registered
     */
    public EntityTask getTask(Class<? extends EntityTask> clazz) {
        return tasksByClass.get(clazz);
    }

    /**
     * Returns a new instance of the task with a given name.
     *
     * @param name the task name to look up
     * @return a task with the given name, or null if none match or the matching task class doesn't
     *         have a parameterless constructor
     */
    public EntityTask getNewTask(String name) {
        // TODO: Refactor to use a constructor-reference Supplier<? extends EntityTask>
        Class<? extends EntityTask> clazz = EntityDirector.getEntityTask(name);
        try {
            if (clazz != null) {
                return clazz.newInstance();
            }
        } catch (InstantiationException | IllegalAccessException e) {
            e.printStackTrace();
        }
        return null;
    }

    /**
     * Rebuild the list of tasks according to {@link EntityDirector#getEntityMobStateTask
     * (EntityType, MobState)}.
     */
    public void updateState() {
        cancelTasks();
        for (String task : EntityDirector
                .getEntityMobStateTask(entity.getType(), entity.getState())) {
            addTask(task);
        }
    }

    /**
     * Cancels and unregisters the given task.
     * @param task the task to cancel
     */
    public void cancel(EntityTask task) {
        task.reset(entity);
        tasksByName.remove(task.getName(), task);
        tasksByClass.remove(task.getClass(), task);
        tasks.remove(task);
    }

    /**
     * Cancels and unregisters all tasks.
     */
    public void cancelTasks() {
        tasks.forEach(task -> task.reset(entity));
        tasksByName.clear();
        tasksByClass.clear();
        tasks.clear();
    }

    public void pulse() {
        tasks.forEach(task -> task.pulse(entity));
    }

    /**
     * Add the given task, replacing any existing task with the same name.
     *
     * @param task the task to add
     */
    public void addTask(EntityTask task) {
        if (task != null) {
            String name = task.getName();
            EntityTask oldTask = getTask(name);
            if (oldTask != null) {
                cancel(oldTask);
            }
            tasksByName.put(name, task);
            tasksByClass.put(task.getClass(), task);
            tasks.add(task);
        }
    }

    /**
     * Add the task with this name, or replace it with a new instance if it already exists.
     *
     * @param taskName the task name
     */
    public void addTask(String taskName) {
        EntityTask oldTask = getTask(taskName);
        if (oldTask != null) {
            cancel(oldTask);
        }
        EntityTask newTask = getNewTask(taskName);
        tasksByName.put(taskName, newTask);
        tasksByClass.put(newTask.getClass(), newTask);
        tasks.add(newTask);
    }
}

public final class TypeDescriptorString implements TypeDescriptor<String> {

    /**
     * In this bytes will be stored actual string length.
     */
    public static final int LENGTH_OF_METADATA_IN_BYTES = 4;

    /**
     * Maximum length of stored string.
     */
    private final int maxLength;

    /**
     * Charset used for converting from Java UTF-8 to byte array.
     */
    private final Charset charset;

    /**
     * Helps to store actual length of string in bytes.
     */
    private final TypeDescriptorInteger typeDescriptorInteger;

    /**
     *
     * @param maxBytes
     *            required maximum length of field in bytes
     * @param chset
     *            required {@link Charset}
     */
    public TypeDescriptorString(final int maxBytes, final Charset chset) {
        this.maxLength = maxBytes;
        this.charset = Objects.requireNonNull(chset);
        this.typeDescriptorInteger = new TypeDescriptorInteger();
    }

    @Override
    public int getMaxLength() {
        return maxLength + LENGTH_OF_METADATA_IN_BYTES;
    }

    @Override
    public void save(final byte[] data, final int from, final String value) {
        Wrapper<String> w = Wrapper.make(value, this);
        save(data, from, w);
    }

    @Override
    public void save(final byte[] data, final int from,
            final Wrapper<String> value) {
        System.arraycopy(value.getBytes(), 0, data, from,
                value.getBytes().length);
    }

    @Override
    public String load(final byte[] data, final int from) {
        final Integer currentLength = typeDescriptorInteger.load(data, from);
        byte[] b = new byte[currentLength];
        System.arraycopy(data, from + typeDescriptorInteger.getMaxLength(), b,
                0, currentLength);
        return new String(b, charset);
    }

    @Override
    public void verifyType(final Object object) {
        Objects.requireNonNull(object);
        if (!(object instanceof String)) {
            throw new JblinktreeException("Object of wrong type ("
                    + object.getClass().getName() + ")");
        }
    }

    @Override
    public String toString() {
        StringBuilder buff = new StringBuilder(
                "TypeDescriptorString{maxLength=");
        buff.append(getMaxLength());
        buff.append("}");
        return buff.toString();
    }

    /**
     * @return the charset
     */
    public Charset getCharset() {
        return charset;
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + charset.hashCode();
        result = prime * result + maxLength;
        return result;
    }

    @Override
    public boolean equals(final Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null) {
            return false;
        }
        if (getClass() != obj.getClass()) {
            return false;
        }
        TypeDescriptorString other = (TypeDescriptorString) obj;
        if (charset == null) {
            if (other.charset != null) {
                return false;
            }
        } else if (!charset.equals(other.charset)) {
            return false;
        }
        return maxLength == other.maxLength;
    }

    @Override
    public int cmp(final byte[] node, final int start,
            final Wrapper<String> wrapper) {
        byte[] value = wrapper.getBytes();
        final Integer currentLength = typeDescriptorInteger.load(value, 0);
        final int start2 = typeDescriptorInteger.getMaxLength() + start;
        for (int i = 0; i < currentLength; i++) {
            final int cmp = node[start2 + i]
                    - value[i + typeDescriptorInteger.getMaxLength()];
            if (cmp != 0) {
                return cmp;
            }
        }
        return 0;
    }

    @Override
    public byte[] getBytes(final String value) {
        byte[] b = value.getBytes(charset);
        final Integer currentLength = Math.min(b.length, maxLength);
        byte[] out = new byte[currentLength
                + typeDescriptorInteger.getMaxLength()];
        typeDescriptorInteger.save(out, 0, currentLength);
        System.arraycopy(b, 0, out, typeDescriptorInteger.getMaxLength(),
                currentLength);
        return out;
    }

}

public class LineNumberReader extends BufferedReader {

    private int lineNumber;

    private int markedLineNumber = -1;

    private boolean lastWasCR;

    private boolean markedLastWasCR;

    /**
     * Constructs a new buffered LineNumberReader on the Reader <code>in</code>.
     * The default buffer size (8K) is allocated and all reads can now be
     * filtered through this LineNumberReader.
     * 
     * @param in
     *            the Reader to buffer reads on.
     */
    public LineNumberReader(Reader in) {
        super(in);
    }

    /**
     * Constructs a new buffered LineNumberReader on the Reader <code>in</code>.
     * The buffer size is specified by the parameter <code>size</code> and all
     * reads can now be filtered through this LineNumberReader.
     * 
     * @param in
     *            the Reader to buffer reads on.
     * @param size
     *            the size of buffer to allocate.
     */
    public LineNumberReader(Reader in, int size) {
        super(in, size);
    }

    /**
     * Answers a int representing the current line number for this
     * LineNumberReader.
     * 
     * @return int the current line number.
     */
    public int getLineNumber() {
        synchronized (lock) {
            return lineNumber;
        }
    }

    /**
     * Set a Mark position in this LineNumberReader. The parameter
     * <code>readLimit</code> indicates how many characters can be read before
     * a mark is invalidated. Sending reset() will reposition the reader back to
     * the marked position provided <code>readLimit</code> has not been
     * surpassed. The lineNumber associated with this marked position will also
     * be saved and restored when reset() is sent provided
     * <code>readLimit</code> has not been surpassed.
     * 
     * @param readlimit
     *            an int representing how many characters must be read before
     *            invalidating the mark.
     * 
     * @throws IOException
     *             If an error occurs attempting mark this LineNumberReader.
     */
    @Override
    public void mark(int readlimit) throws IOException {
        synchronized (lock) {
            super.mark(readlimit);
            markedLineNumber = lineNumber;
            markedLastWasCR = lastWasCR;
        }
    }

    /**
     * Reads a single char from this LineNumberReader and returns the result as
     * an int. The low-order 2 bytes are returned or -1 of the end of reader was
     * encountered. This implementation returns a char from the target reader.
     * The line number count is incremented if a line terminator is encountered.
     * A line delimiter sequence is determined by '\r', '\n', or '\r\n'. In this
     * method, the sequence is always translated into '\n'.
     * 
     * @return int The char read or -1 if end of reader.
     * 
     * @throws IOException
     *             If the reader is already closed or another IOException
     *             occurs.
     */
    @Override
    public int read() throws IOException {
        synchronized (lock) {
            int ch = super.read();
            if (ch == '\n' && lastWasCR) {
                ch = super.read();
            }
            lastWasCR = false;
            switch (ch) {
                case '\r':
                    ch = '\n';
                    lastWasCR = true;
                    // fall through
                case '\n':
                    lineNumber++;
            }
            return ch;
        }
    }

    /**
     * Reads at most <code>count</code> chars from this LineNumberReader and
     * stores them in char array <code>buffer</code> starting at offset
     * <code>offset</code>. Answer the number of chars actually read or -1 if
     * no chars were read and end of reader was encountered. This implementation
     * reads chars from the target stream. The line number count is incremented
     * if a line terminator is encountered. A line delimiter sequence is
     * determined by '\r', '\n', or '\r\n'. In this method, the sequence is
     * always translated into '\n'.
     * 
     * @param buffer
     *            the char array in which to store the read chars.
     * @param offset
     *            the offset in <code>buffer</code> to store the read chars.
     * @param count
     *            the maximum number of chars to store in <code>buffer</code>.
     * @return the number of chars actually read or -1 if end of reader.
     * 
     * @throws IOException
     *             If the reader is already closed or another IOException
     *             occurs.
     */

    @Override
    public int read(char[] buffer, int offset, int count) throws IOException {
        synchronized (lock) {
            int read = super.read(buffer, offset, count);
            if (read == -1) {
                return -1;
            }
            for (int i = 0; i < read; i++) {
                char ch = buffer[offset + i];
                if (ch == '\r') {
                    lineNumber++;
                    lastWasCR = true;
                } else if (ch == '\n') {
                    if (!lastWasCR) {
                        lineNumber++;
                    }
                    lastWasCR = false;
                } else {
                    lastWasCR = false;
                }
            }
            return read;
        }
    }

    /**
     * Answers a <code>String</code> representing the next line of text
     * available in this LineNumberReader. A line is represented by 0 or more
     * characters followed by <code>'\n'</code>, <code>'\r'</code>,
     * <code>"\n\r"</code> or end of stream. The <code>String</code> does
     * not include the newline sequence.
     * 
     * @return String the contents of the line or null if no characters were
     *         read before end of stream.
     * 
     * @throws IOException
     *             If the LineNumberReader is already closed or some other IO
     *             error occurs.
     */
    @Override
    public String readLine() throws IOException {
        synchronized (lock) {
            /* Typical Line Length */
            StringBuilder result = new StringBuilder(80);
            while (true) {
                int character = read();
                if (character == -1) {
                    return result.length() != 0 ? result.toString() : null;
                }
                if (character == '\n') {
                    return result.toString();
                }
                result.append((char) character);
            }
        }
    }

    /**
     * Reset this LineNumberReader to the last marked location. If the
     * <code>readlimit</code> has been passed or no <code>mark</code> has
     * been set, throw IOException. This implementation resets the target
     * reader. It also resets the line count to what is was when this reader was
     * marked.
     * 
     * @throws IOException
     *             If the reader is already closed or another IOException
     *             occurs.
     */
    @Override
    public void reset() throws IOException {
        synchronized (lock) {
            super.reset();
            lineNumber = markedLineNumber;
            lastWasCR = markedLastWasCR;
        }
    }

    /**
     * Sets the lineNumber of this LineNumberReader to the specified
     * <code>lineNumber</code>. Note that this may have side effects on the
     * line number associated with the last marked position.
     * 
     * @param lineNumber
     *            the new lineNumber value.
     */
    public void setLineNumber(int lineNumber) {
        synchronized (lock) {
            this.lineNumber = lineNumber;
        }
    }

    /**
     * Skips <code>count</code> number of chars in this LineNumberReader.
     * Subsequent <code>read()</code>'s will not return these chars unless
     * <code>reset()</code> is used. This implementation skips
     * <code>count</code> number of chars in the target stream and increments
     * the lineNumber count as chars are skipped.
     * 
     * @param count
     *            the number of chars to skip.
     * @return the number of chars actually skipped.
     * 
     * @throws IOException
     *             If the reader is already closed or another IOException
     *             occurs.
     */
    @Override
    public long skip(long count) throws IOException {
        if (count < 0) {
            throw new IllegalArgumentException();
        }
        synchronized (lock) {
            for (int i = 0; i < count; i++) {
                if (read() == -1) {
                    return i;
                }
            }
            return count;
        }
    }
}

