public static void sanitizeDocument(final PDFDocument document, final URL sanitizedUrl)
                    throws PDFInvalidDocumentException, PDFIOException, PDFSecurityException, PDFFontException,
                    PDFConfigurationException, PDFInvalidParameterException, PDFUnableToCompleteOperationException {
        if (!canSanitizeDocument(document)) {
            LOGGER.warn("The document was not sanitized");
            return;
        }
        ByteWriter writer = null;
        try {
            writer = IoUtils.newByteWriter(sanitizedUrl);
        } catch (final IOException e) {
            throw new PDFIOException(e);
        }
        final PDFSaveOptions saveOptions = PDFSaveLinearOptions.newInstance();
        saveOptions.setForceCompress(true);
        final SanitizationOptions options = new SanitizationOptions();
        options.setPDFFontSet(FontSetLoader.newInstance().getFontSet());
        options.setSaveOptions(saveOptions);
        SanitizationService.sanitizeDocument(document, options, writer);
    }

public void loadFolder(File folder) {
		LinearLayout root = this.chooser.getRootLayout();
		LinearLayout layout = (LinearLayout) root.findViewById(R.id.linearLayoutFiles);
		layout.removeAllViews();
		if(folder == null || !folder.exists()) {
			if(defaultFolder != null) {
				this.currentFolder = defaultFolder;			
			} else {
				this.currentFolder = Environment.getExternalStorageDirectory();
			}
		} else {
			this.currentFolder = folder;
		}
		if(this.currentFolder.exists() && layout != null) {
			List<FileItem> fileItems = new LinkedList<FileItem>();
			if(this.currentFolder.getParent() != null) {
				File parent = new File(this.currentFolder.getParent());
				if(parent.exists()) {
					fileItems.add(new FileItem(this.chooser.getContext(), parent, ".."));					
				}
			}
			if(this.currentFolder.isDirectory()) {
				File[] fileList = this.currentFolder.listFiles();
				if(fileList != null) {
					Arrays.sort(fileList, new Comparator<File>() {
						public int compare(File file1, File file2) {
							if(file1 != null && file2 != null) {
								if(file1.isDirectory() && (!file2.isDirectory())) return -1;
								if(file2.isDirectory() && (!file1.isDirectory())) return 1;
								return file1.getName().compareTo(file2.getName());
							}
							return 0;
						}
					});		
					for(int i=0; i<fileList.length; i++) {
						boolean selectable = true;
						if(!fileList[i].isDirectory()) {
							selectable = !this.folderMode && (this.filter == null || fileList[i].getName().matches(this.filter));
						}
						if(selectable || !this.showOnlySelectable) {
							FileItem fileItem = new FileItem(this.chooser.getContext(), fileList[i]);
							fileItem.setSelectable(selectable);
							fileItems.add(fileItem);
						}
					}
				}
				String currentFolderName = this.showFullPathInTitle? this.currentFolder.getPath() : this.currentFolder.getName();
				this.chooser.setCurrentFolderName(currentFolderName);
			} else {
				fileItems.add(new FileItem(this.chooser.getContext(), this.currentFolder));
			}
			for(int i=0; i<fileItems.size(); i++) {
				fileItems.get(i).addListener(this.fileItemClickListener);
				layout.addView(fileItems.get(i));
			}
			defaultFolder = this.currentFolder;
		}			
	}

public void replaceCode(List<File> files) {
        List<ReplaceItem> items = this.items;
        List<File> targetFiles = new ArrayList<>();
        for (int i = 0; i < files.size(); i++) {
            File file = files.get(i);
            String fileStr = FileUtil.convertFileToString(file);
            if (fileStr == null) {
                Console.errorLine("!! null: " + file.getAbsolutePath());
            }
            for (ReplaceItem item : items) {
                if (fileStr.contains(item.getSrc())) {
                    //Console.logLine("检测到需要修改：" + file.getName());
                    targetFiles.add(file);
                    break;
                }
            }
        }
        for (File targetFile : targetFiles) {
            //https://stackoverflow.com/questions/1096621/read-string-line-by-line
            StringBuilder builder = new StringBuilder();
            List<String> strList = FileUtil.convertFileToStringList(targetFile);
            for (String s : strList) { // code of 1 line
                builder.append(getReplacedLine(s));
            }
            try {
                targetFile.setWritable(true);
                FileUtil.writeString(targetFile, builder.toString());
                String s = StringUtil.rPad("√ 修改代码：" + targetFile.getName(), 40);
                Console.logLine(s + " => " + targetFile.getAbsolutePath());
            } catch (IOException e) {
                Console.logLine("!! ERROR: write to file fail: " + targetFile.getAbsolutePath());
                Console.logLine(e.getMessage());
                e.printStackTrace();
            }
        }
    }

