public static PathWatcher createSinglePathWatcher(
            Path path,
            PathChangeListener pathChangeListener,
            ExecutorService executorService,
            LifecycleListener lifecycleListener){
        Preconditions.isNotNull(path, "path");
        Preconditions.isNotNull(pathChangeListener, "pathChangeListener");
        Preconditions.isNotNull(executorService, "executorService");
        Preconditions.isNotNull(lifecycleListener, "lifecycleListener");
        PathWatcherFactory pathWatcherFactory = new PathWatcherFactory(executorService, lifecycleListener);
        return pathWatcherFactory.createNonRecursiveWatcher(path.getParent(),
                new SinglePathChangeListener(path, pathChangeListener));
    }

public static Set<Method> retrieveMethods (final Class<?> objClass, final Class<? extends Annotation> annotationClass) {
		final Set<Method> methods = new HashSet<>();
		for (final Method method : objClass.getMethods()) {
			if (annotationClass == null || method.getAnnotation(annotationClass) != null) {
				if (LG.isLoggable(Level.FINE)) {
					LG.fine("Added method: " + method.getName());
				}
				methods.add(method);
			}
		}
		return methods;
	}

public void require(final String... requiredColumns) throws MissingColumnException {
		if (requiredColumns == null || requiredColumns.length < 1) {
			return;
		}
		final ArrayList<String> missingColumns = new ArrayList<>();
		for (final String requiredColumn : requiredColumns) {
			if (!hasColumn(requiredColumn)) {
				missingColumns.add(requiredColumn);
			}
		}
		if (missingColumns.size() > 0) {
			throw new MissingColumnException(StringUtils.join(",", missingColumns), missingColumns);
		}
	}

public static NotificationCompat.Builder createHangup(String channelName) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            NotificationManagerCompat manager = getManager();
            NotificationChannel mChannel = manager.getNotificationChannel(channelName);
            if (mChannel == null) {
                mChannel = new NotificationChannel(channelName, channelName,
                        android.app.NotificationManager.IMPORTANCE_HIGH);
                mChannel.setSound(null, null);
                manager.createNotificationChannel(mChannel);
            }
        }
        NotificationCompat.Builder builder = new NotificationCompat.Builder(
                ContextProvider.get(), channelName);
        builder.setSmallIcon(DEFAULT_ICON)
                .setContentTitle(defaultTitle)
                .setContentText(" ")
                .setFullScreenIntent(null, true)
                .setAutoCancel(true);
        return builder;
    }

