import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.time.LocalDateTime;

public class PerformanceMonitor {
    private long startTime;
    private long endTime;
    private int successCount;
    private int errorCount;
    private String logFilePath;

    public PerformanceMonitor(String logFilePath) {
        this.logFilePath = logFilePath;
        this.successCount = 0;
        this.errorCount = 0;
    }

    public void startJob() {
        startTime = System.currentTimeMillis();
    }

    public void endJob(boolean success) {
        endTime = System.currentTimeMillis();
        if (success) {
            successCount++;
        } else {
            errorCount++;
        }
        logPerformance(success);
    }

    private void logPerformance(boolean success) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFilePath, true))) {
            String status = success ? "SUCCESS" : "ERROR";
            long executionTime = endTime - startTime;
            String logEntry = String.format("%s | Job Status: %s | Execution Time: %d ms | Total Successful: %d | Total Errors: %d%n",
                LocalDateTime.now(), status, executionTime, successCount, errorCount);
            writer.write(logEntry);
        } catch (IOException e) {
            e.printStackTrace(); // consider logging the error in a more robust way in production
        }
    }

    public static void main(String[] args) {
        PerformanceMonitor monitor = new PerformanceMonitor("performance_log.txt");

        monitor.startJob();
        try {
            // Simulate a data processing job
            Thread.sleep(1000); // Simulated workload
            monitor.endJob(true);
        } catch (InterruptedException e) {
            monitor.endJob(false);
        }
    }
}

class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;

        // Check each element in the matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i == j || i + j == n - 1)) { // Check diagonal elements
                    if (grid[i][j] == 0) return false; // Not on a diagonal; it must be zero
                } else { // Not on a diagonal
                    if (grid[i][j] != 0) return false; // On a non-diagonal; it must be non-zero
                }
            }
        }

        return true; // All elements checked and conditions met
    }
}

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int max = Arrays.stream(nums).max().getAsInt();
        int atLeastK = 0;
        int start = 0;
        long count = 0;

        for (int end = 0; end < nums.length; end++) {
            if (nums[end] == max) atLeastK++;

            while (atLeastK >= k) {
                count += nums.length - end;
                if (nums[start] == max) atLeastK--;
                start++;
            }
        }

        return count;
    }
}

import java.util.Scanner;

class Main
{
    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        int num = sc.nextInt();
        sc.nextLine();
        int count = 0;

        // count the number of proper divisors
        int forLoopCount = num+1;
        boolean[] prime = new boolean[forLoopCount];
        for(int i=2; i<=forLoopCount; i++){
            prime[i]=true;
        }
        for(int i=2; i*i<=num; i++){
            if(prime[i]!=false){
                for(int j=i*i; j<=forLoopCount; j+=i){
                    prime[j]=false;
                }
            }
        }       
        int temporaryCount=0;
        // count the number of prime divisors
        for(int i=2; i<=num; i++){
            if(prime[i]!=false){
                temporaryCount++;
            }
        }
        // count the number of exponentials
        int divisionCount=0;
        for(int i=2; i<=num; i++){
            if(prime[i]==false){
                int power=0;
                int n=i;
                while(n>1){
                    if(n%i==0){
                        n=n/i;
                        power++;
                    }else{
                        break;
                    }
                }
                divisionCount=divisionCount+power;
                temporaryCount=temporaryCount-power;
            }
        }   

        // subtract the number of exponentials from the total number of divisors
        count += divisionCount;
        // add the number of prime divisors to the number of proper divisors
        count += temporaryCount;

        System.out.println(count-1);
    }
}

