import java.util.*;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (matchPattern(word, pattern)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean matchPattern(String word, String pattern) {
        Map<Character, Character> pToW = new HashMap<>();
        Map<Character, Character> wToP = new HashMap<>();

        for (int i = 0; i < word.length(); i++) {
            char p = pattern.charAt(i);
            char w = word.charAt(i);

            if (!pToW.containsKey(p) &&!wToP.containsKey(w)) {
                pToW.put(p, w);
                wToP.put(w, p);
            } else if (pToW.getOrDefault(p, ' ')!= w || wToP.getOrDefault(w, ' ')!= p) {
                return false;
            }
        }
        return true;
    }
}

import java.util.PriorityQueue;

class Solution {
    public int halveArray(int[] nums) {
        double target = 0.0;
        PriorityQueue<Double> pq = new PriorityQueue<>((a, b) -> Double.compare(b, a));

        for (int num : nums) {
            target += num;
            pq.offer((double) num);
        }

        target /= 2.0;
        int operations = 0;
        double reducedSum = 0.0;

        while (reducedSum < target) {
            double largest = pq.poll();
            reducedSum += largest / 2.0;
            pq.offer(largest / 2.0);
            operations++;
        }

        return operations;
    }
}

import java.util.PriorityQueue;

public class Main {
    public static int maximumScore(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int num : nums) {
            pq.offer(num);
        }

        int score = 0;
        while (k-- > 0) {
            int num = pq.poll();
            score += num;
            pq.offer((num + 2) / 3);
        }

        return score;
    }

    public static void main(String[] args) {
        int[] nums = {10, 10, 10, 10, 10};
        int k = 5;
        System.out.println(maximumScore(nums, k)); // Output: 50

        int[] nums2 = {1, 10, 3, 3, 3};
        int k2 = 3;
        System.out.println(maximumScore(nums2, k2)); // Output: 17
    }
}

import android.view.View;
import android.animation.Animator;
import java.util.ArrayList;
import java.util.List;

public class BoundView {
    private final View boundView;
    private final int anchorOffset;
    private final List<Transformation> transformations;

    public BoundView(View view, List<Transformation> transformations) {
        this.boundView = view;
        this.anchorOffset = 0; // Default value, can be modified as needed
        this.transformations = new ArrayList<>(transformations);
    }

    public void applyTransform(float currentMoveY) {
        for (Transformation transformation : transformations) {
            transformation.apply(boundView, currentMoveY);
        }
    }

    public List<Animator> generateAnimators(float progress) {
        List<Animator> animators = new ArrayList<>();
        for (Transformation transformation : transformations) {
            Animator animator = transformation.createAnimator(boundView, anchorOffset, progress);
            if (animator != null) {
                animators.add(animator);
            }
        }
        return animators;
    }

    public interface Transformation {
        void apply(View view, float currentMoveY);
        Animator createAnimator(View view, int anchorOffset, float progress);
    }
}

import net.minecraft.client.gui.GuiButton;
